// ── Parse do CSV de investimentos ───────────────────────────────────────────
// O HTTP Request devolve o data.csv como texto puro. Aqui ele vira um array
// de objetos { perfil, produto, minimo, rentabilidade }.

const bruto = $json.data ?? $json.body ?? $json;
const texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);

const linhas = texto.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
const cabecalho = linhas[0].split(',').map((h) => h.trim());

const investimentos = linhas.slice(1).map((linha) => {
  const colunas = linha.split(',').map((c) => c.trim());
  const obj = {};
  cabecalho.forEach((h, i) => {
    obj[h] = colunas[i] ?? '';
  });
  // "minimo" vem como texto no CSV; normalizamos para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, '')) || 0;
  return obj;
});

return [{ json: { investimentos } }];

// ── Monta um prompt por cliente para o Agente de IA (Etapa 5) ───────────────
const entrada = $input.first().json;
const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

const paraNumero = (texto) => {
  if (typeof texto === 'number') return texto;
  const limpo = String(texto).replace(/[^\d,]/g, '').replace(',', '.');
  return Number(limpo) || 0;
};

return clientes.map((cliente) => {
  const saldo = paraNumero(cliente.saldo);
  const opcoes = investimentos.filter((i) => i.perfil === cliente.perfil);

  const catalogo = opcoes
    .map((i) => `- ${i.produto} | mínimo R$ ${i.minimo} | rentabilidade ${i.rentabilidade}`)
    .join('\n');

  const prompt = [
    'Você é um assistente de investimentos de um banco brasileiro.',
    'Escreva UMA mensagem curta (máx. 3 frases), em português do Brasil, tom cordial e profissional.',
    'Não invente produtos: use apenas os do catálogo abaixo.',
    'Não prometa retorno garantido e não use linguagem de venda agressiva.',
    '',
    `Cliente: ${cliente.nome}`,
    `Perfil: ${cliente.perfil}`,
    `Saldo disponível: ${cliente.saldo}`,
    '',
    'Catálogo disponível para esse perfil:',
    catalogo,
  ].join('\n');

  return { json: { ...cliente, saldo_numerico: saldo, prompt } };
});

// ── Consolida a saída do LLM no mesmo formato do MVP ────────────────────────
const itens = $input.all();

const recomendacoes = itens.map((item) => {
  const j = item.json;
  const texto = j.text ?? j.output ?? j.response ?? j.mensagem ?? '';
  return {
    nome: j.nome,
    email: j.email,
    saldo: j.saldo,
    perfil: j.perfil,
    mensagem: String(texto).trim(),
  };
});

return [
  {
    json: {
      ok: true,
      gerado_em: new Date().toISOString(),
      origem: 'LLM (Google Gemini)',
      total_clientes: recomendacoes.length,
      recomendacoes,
    },
  },
];
